use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,collections::BTreeSet};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-eight-window-colors176";
const W:usize=8;const B:usize=2048;const TILE:usize=1600;
type Words=[u64;4];type Codes=[[i16;8];2];
mod split;include!("grouping-body.rs");
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn code(word:Words)->Codes{let s=split::phi_split(word);std::array::from_fn(|p|std::array::from_fn(|w|{let i=2*p;let d=split::booth(&[s[i],s[i+1]&0x7fff_ffff_ffff_ffff,0,0],w,12);if s[i+1]>>63!=0{-d}else{d}}))}
fn b(d:i16)->usize{assert!(d!=0);let k=d.unsigned_abs()as usize-1;assert!(k<B);k}
fn main(){let target=format!("{R}/obstruction-result.json");assert!(!std::path::Path::new(&target).exists());
 let exit:Value=serde_json::from_slice(&fs::read(format!("{R}/runs/fixture-census/exit.json")).unwrap()).unwrap();assert_eq!(exit["returncode"],101);assert_eq!(exit["success"],false);
 let tests=fs::read_to_string(format!("{R}/runs/schedule-tests/stdout.log")).unwrap();assert!(tests.contains("2 passed; 0 failed"));
 let inputs:Value=serde_json::from_slice(&fs::read("/home/ubuntu/src/zopro-perf-work/g2-joint-ring-screen176/inputs.json").unwrap()).unwrap();let mut cases=vec![];
 for(name,input)in inputs.as_object().unwrap(){let bytes=fs::read(input["file"].as_str().unwrap()).unwrap();assert_eq!(hash(&bytes),input["sha256"].as_str().unwrap());assert_eq!(&bytes[..8],b"B2SCAN01");let n=u64::from_le_bytes(bytes[8..16].try_into().unwrap())as usize;assert_eq!(bytes.len(),16+160*n);
 let words=bytes[16+128*n..].chunks_exact(32).map(|v|std::array::from_fn(|i|u64::from_le_bytes(v[8*i..8*i+8].try_into().unwrap()))).collect::<Vec<Words>>();let grouped=grouping(&words);let effective=grouped.as_deref().unwrap_or(&words);let codes=effective.iter().copied().map(code).collect::<Vec<_>>();let chunk=codes.len().div_ceil(16);
 let(mut arrivals,mut firsts,mut phi,mut vector_rows,mut active)=(0u64,0u64,0u64,0u64,0u64);let mut hist=[0u64;9];let mut tiles=vec![];let mut worst=Value::Null;let mut first_violation=Value::Null;
 for part in 0..16{let start=part*chunk;let end=(start+chunk).min(codes.len());let mut occupied=vec![vec![false;B];W];
 for phase in[1usize,0]{for begin in(start..end).step_by(TILE){let last=(begin+TILE).min(end);let before=occupied.clone();let mut counts=vec![vec![0u16;B];W];let(mut row_count,mut pairs)=(0usize,0usize);let mut tile_first_violation=Value::Null;
 for i in begin..last{let mut mask=0u8;for w in 0..W{let d=codes[i][phase][w];if d==0{continue;}arrivals+=1;let k=b(d);if occupied[w][k]{mask|=1<<w;counts[w][k]+=1;if counts[w][k]==201&&tile_first_violation.is_null(){tile_first_violation=json!({"case":name,"part":part,"phase":phase,"window":w,"bucket_index":k,"tile_start":begin,"tile_end":last,"global_row":i,"tile_row":i-begin,"required_distinct_colors":201});}}else{occupied[w][k]=true;firsts+=1;}}
 let k=mask.count_ones()as usize;hist[k]+=1;if k>0{row_count+=1;vector_rows+=1;}pairs+=k;active+=k as u64;}
 if first_violation.is_null()&&!tile_first_violation.is_null(){first_violation=tile_first_violation;}
 let(mut max_count,mut win,mut bucket)=(0u16,0,0);for w in 0..W{for k in 0..B{if counts[w][k]>max_count{max_count=counts[w][k];win=w;bucket=k;}}}
 let lower=(max_count as usize).max(row_count.div_ceil(200));
 let tile=json!({"part":part,"part_start":start,"part_end":end,"phase":phase,"tile_start":begin,"tile_end":last,"active_rows":row_count,"active_pairs":pairs,"maximum_bucket_clique":max_count,"clique_window":win,"clique_bucket_index":bucket,"color_count_lower_bound":lower,"cap200_impossible":lower>200});
 if worst.is_null()||max_count as u64>worst["maximum_bucket_clique"].as_u64().unwrap(){let mut seen=before[win][bucket];let mut indices=vec![];for i in begin..last{let d=codes[i][phase][win];if d!=0&&b(d)==bucket{if seen{indices.push(i as u64);}else{seen=true;}}}assert_eq!(indices.len(),max_count as usize);let index_bytes=indices.iter().flat_map(|i|i.to_le_bytes()).collect::<Vec<_>>();worst=tile.clone();worst["active_row_indices_sha256"]=json!(hash(&index_bytes));worst["first_active_row"]=json!(indices.first());worst["last_active_row"]=json!(indices.last());}
 tiles.push(tile);
 }if phase==1{phi+=occupied.iter().flatten().filter(|&&v|v).count()as u64;}}
 }
 let violated=tiles.iter().filter(|v|v["cap200_impossible"]==true).count();assert_eq!(active,hist.iter().enumerate().map(|(k,&v)|k as u64*v).sum::<u64>());assert_eq!(vector_rows,hist[1..].iter().sum::<u64>());assert_eq!(arrivals,firsts+active);
 cases.push(json!({"case":name,"raw_rows":n,"effective_rows":codes.len(),"grouping_selected":grouped.is_some(),"fixture_sha256":hash(&bytes),"arrivals":arrivals,"first_assignments":firsts,"active_fill_pairs":active,"masked_vector_rows_if_unbounded_schedule":vector_rows,"inactive_lane_slots_if_unbounded_schedule":8*vector_rows-active,"fill_lane_utilization_if_unbounded_schedule":active as f64/(8*vector_rows)as f64,"mask_histogram":hist,"vector_fill_V_excluding_all_bridges":7*vector_rows,"vector_fill_F":5*vector_rows,"phi_point_maps_before_part_merges":phi,"phi_scalar_Fq_multiplications":2*phi,"tile_count":tiles.len(),"tiles_provably_exceeding_color_cap":violated,"first_necessary_cap_violation":first_violation,"worst_clique_certificate":worst,"tiles":tiles}));
 }
 let result=json!({"complete":true,"kind":"post-refusal_dependency_obstruction_audit","parent_workflow_success":false,"parent_model_returncode":101,"parent_model_completed":false,"parent_synthetic_tests_passed":2,"parent_synthetic_schedule_cases":48,"rerun_of_parent_model_or_tests":false,"cases":cases,"SDK_requests":0,"Gnark_exports":0,"production_changed":false,"adopted":false,"native_measurement_selected":false,"canonical_verified_proof_count":36477,"goal_achieved":false,"payload":{"original_affine_buckets_bytes":4194304,"candidate_affine_buckets_bytes":33554432,"scheduler_payload_upper_per_actor_bytes":504896,"prefix_payload_upper_per_actor_bytes":128000},"limitations":["No actual color schedule completed on real fixtures; no inverse/batch saving or caller timing established","Hypothetical masked fill arithmetic excludes bridges, part merges, scalar costs, exceptions, masking, scheduling and memory traffic","Formal dependency and signed-token tests do not qualify native EC/proof behavior","Payload is not measured allocation/RSS, minimum RAM or low-memory behavior"]});
 fs::write(target,serde_json::to_vec_pretty(&result).unwrap()).unwrap();for c in result["cases"].as_array().unwrap(){println!("{}: {}/{} tiles exceed cap; worst clique {}; first violation row {}; hypothetical fill utilization {}",c["case"],c["tiles_provably_exceeding_color_cap"],c["tile_count"],c["worst_clique_certificate"]["maximum_bucket_clique"],c["first_necessary_cap_violation"]["tile_row"],c["fill_lane_utilization_if_unbounded_schedule"]);}
}
